65	 */
66	
67	@RestController
68	@CrossOrigin(exposedHeaders = "errors, content-type")
69	@RequestMapping("/api")
70	public class OwnerRestControllerV1 implements OwnersApi {
71	
72	    /**
73	     * Dedicated audit logger. A single line is emitted here on each successful owner create,
74	     * carrying the new owner's id, customer code and registration date.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    /**
79	     * Maximum number of owners a single city may hold. A create whose city already contains this many
80	     * owners is rejected with a {@code 409 Conflict} (see {@link #rejectCityAtCapacity}).
81	     */
82	    private static final int MAX_OWNERS_PER_CITY = 50;
83	
84	    /**
85	     * Maximum number of owners that may be registered in a single day. A create made once this many
86	     * owners already carry today's {@code registrationDate} is rejected with a {@code 429 Too Many
87	     * Requests} (see {@link #rejectDailyRegistrationLimitReached}).
88	     */
89	    private static final int MAX_OWNERS_PER_DAY = 100;
90	
91	    /**
92	     * The number of owners that must already carry a given day's {@code registrationDate} before a
93	     * create made that day is flagged with {@code bulkSignupWarning}. Once more than this many owners
94	     * have already been created for the day, the new owner's {@code bulkSignupWarning} is {@code true}.
95	     */
96	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
97	
98	    private final ClinicService clinicService;
99	
100	    private final OwnerMapper ownerMapper;
101	
102	    private final PetMapper petMapper;
103	
104	    private final VisitMapper visitMapper;
105	
106	    public OwnerRestControllerV1(ClinicService clinicService,
107	                                 OwnerMapper ownerMapper,
108	                                 PetMapper petMapper,
109	                                 VisitMapper visitMapper) {
110	        this.clinicService = clinicService;
111	        this.ownerMapper = ownerMapper;
112	        this.petMapper = petMapper;
113	        this.visitMapper = visitMapper;
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
119	        Collection<Owner> owners;
120	        if (lastName != null) {
121	            owners = this.clinicService.findOwnerByLastName(lastName);
122	        } else {
123	            owners = this.clinicService.findAllOwners();
124	        }
125	        if (owners.isEmpty()) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
134	        Owner owner = this.clinicService.findOwnerById(ownerId);
135	        if (owner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
144	        normalizeAddress(ownerFieldsDto);
145	        rejectBlankOwnerFields(ownerFieldsDto);
146	        normalizeTelephone(ownerFieldsDto);
147	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
148	        rejectDuplicateHousehold(ownerFieldsDto);
149	        rejectCityAtCapacity(ownerFieldsDto.getCity());
150	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto.getRegistrationDate());
151	        long registeredThatDay = countRegisteredOn(registrationDate);
152	        rejectDailyRegistrationLimitReached(registrationDate, registeredThatDay);
153	        normalizeEmail(ownerFieldsDto);
154	        rejectDuplicateEmail(ownerFieldsDto.getEmail());
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        owner.setRegistrationDate(registrationDate);
158	        owner.setHouseholdId(HouseholdNormalizer.toHouseholdId(owner.getLastName(), owner.getAddress()));
159	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        owner.setBulkSignupWarning(registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD);
161	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
162	        this.clinicService.saveOwner(owner);
163	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
164	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
174	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
175	        if (currentOwner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        currentOwner.setAddress(ownerFieldsDto.getAddress());
179	        currentOwner.setCity(ownerFieldsDto.getCity());
180	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
181	        currentOwner.setLastName(ownerFieldsDto.getLastName());
182	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
183	        normalizeEmail(ownerFieldsDto);
184	        currentOwner.setEmail(ownerFieldsDto.getEmail());
185	        currentOwner.setHouseholdId(
186	            HouseholdNormalizer.toHouseholdId(currentOwner.getLastName(), currentOwner.getAddress()));
187	        this.clinicService.saveOwner(currentOwner);
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Transactional
193	    @Override
194	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
195	        Owner owner = this.clinicService.findOwnerById(ownerId);
196	        if (owner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        this.clinicService.deleteOwner(owner);
200	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
201	    }
202	
203	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
204	    @Override
205	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
206	        Owner owner = this.clinicService.findOwnerById(ownerId);
207	        if (owner == null) {
208	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	        }
210	        HttpHeaders headers = new HttpHeaders();
211	        Pet pet = petMapper.toPet(petFieldsDto);
212	        owner.setId(ownerId);
213	        pet.setOwner(owner);
214	        pet.getType().setName(null);
215	        this.clinicService.savePet(pet);
216	        PetDto petDto = petMapper.toPetDto(pet);
217	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
218	            .buildAndExpand(pet.getId()).toUri());
219	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
225	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
226	        if (currentOwner != null) {
227	            Pet currentPet = this.clinicService.findPetById(petId);
228	            if (currentPet != null) {
229	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
230	                currentPet.setName(petFieldsDto.getName());
231	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
232	                this.clinicService.savePet(currentPet);
233	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
234	            }
235	        }
236	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
242	        HttpHeaders headers = new HttpHeaders();
243	        Visit visit = visitMapper.toVisit(visitFieldsDto);
244	        Pet pet = new Pet();
245	        pet.setId(petId);
246	        visit.setPet(pet);
247	        this.clinicService.saveVisit(visit);
248	        VisitDto visitDto = visitMapper.toVisitDto(visit);
249	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
250	            .buildAndExpand(visit.getId()).toUri());
251	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
252	    }
253	
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner != null) {
260	            Pet pet = owner.getPet(petId);
261	            if (pet != null) {
262	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
263	            }
264	        }
265	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
266	    }
267	
268	    /**
269	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
270	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
271	     * the request body already rejects null and empty values, but permits whitespace-only strings
272	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
273	     * that gap so every required field must carry a non-blank value.
274	     *
275	     * @param ownerFieldsDto the submitted owner fields
276	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
277	     */
278	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
279	        List<String> missing = new ArrayList<>();
280	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
281	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
282	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
283	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
284	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
285	        if (!missing.isEmpty()) {
286	            throw new InvalidOwnerFieldsException(missing);
287	        }
288	    }
289	
290	    private void addIfBlank(List<String> missing, String fieldName, String value) {
291	        if (value == null || value.isBlank()) {
292	            missing.add(fieldName);
293	        }
294	    }
295	
296	    /**
297	     * Normalizes the submitted {@code address} on create to its canonical form (see
298	     * {@link AddressNormalizer#normalize}) and writes it back onto the request so it is the value
299	     * stored and returned, and the form every later address comparison (the required-field check,
300	     * household duplicate detection and the shared household id) is judged on. A null address is left
301	     * untouched so {@link #rejectBlankOwnerFields} still reports it as missing; a value that is blank
302	     * after normalization likewise reduces to the empty string and is rejected there.
303	     *
304	     * @param ownerFieldsDto the submitted owner fields
305	     */
306	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
307	        String address = ownerFieldsDto.getAddress();
308	        if (address == null) {
309	            return;
310	        }
311	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(address));
312	    }
313	
314	    /**
315	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
316	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
317	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
318	     * {@code 400 Bad Request}.
319	     *
320	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
321	     *                       {@link #rejectBlankOwnerFields} having already run)
322	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
323	     */
324	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
325	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
326	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
327	        ownerFieldsDto.setTelephone(normalized);
328	    }
329	
330	    /**
331	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
332	     * untouched (email is optional). When present it is reduced to its canonical form (see
333	     * {@link EmailNormalizer#normalize}) and written back so it is the value stored and returned. Any
334	     * present-but-invalid address is rejected with a {@code 400 Bad Request}.
335	     *
336	     * @param ownerFieldsDto the submitted owner fields
337	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
338	     */
339	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
340	        String email = ownerFieldsDto.getEmail();
341	        if (email == null || email.isBlank()) {
342	            return;
343	        }
344	        String normalized = EmailNormalizer.normalize(email)
345	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("email")));
346	        ownerFieldsDto.setEmail(normalized);
347	    }
348	
349	    /**
350	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
351	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
352	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
353	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
354	     *
355	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
356	     *                            {@link #normalizeTelephone}
357	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
358	     */
359	    private void rejectDuplicateTelephone(String normalizedTelephone) {
360	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
361	        boolean inUse = this.clinicService.findAllOwners().stream()
362	            .map(Owner::getTelephone)
363	            .filter(Objects::nonNull)
364	            .map(TelephoneNormalizer::toComparisonKey)
365	            .anyMatch(comparisonKey::equals);
366	        if (inUse) {
367	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
368	        }
369	    }
370	
371	    /**
372	     * Rejects creating an owner whose lower-cased email is already used by any other owner. Both the
373	     * submitted email and every existing owner's stored email are reduced to their
374	     * {@linkplain EmailNormalizer#toComparisonKey comparison key} before comparison, so equality is
375	     * judged on that key alone. A match is reported as a {@code 409 Conflict}. An absent (null or
376	     * blank) email is not subject to this rule, email being optional.
377	     *
378	     * @param normalizedEmail the submitted email, already trimmed and lower-cased by
379	     *                        {@link #normalizeEmail}, or null/blank when no email was supplied
380	     * @throws DuplicateOwnerEmailException if another owner already uses the same email
381	     */
382	    private void rejectDuplicateEmail(String normalizedEmail) {
383	        if (normalizedEmail == null || normalizedEmail.isBlank()) {
384	            return;
385	        }
386	        String comparisonKey = EmailNormalizer.toComparisonKey(normalizedEmail);
387	        boolean inUse = this.clinicService.findAllOwners().stream()
388	            .map(Owner::getEmail)
389	            .filter(Objects::nonNull)
390	            .map(EmailNormalizer::toComparisonKey)
391	            .anyMatch(comparisonKey::equals);
392	        if (inUse) {
393	            throw new DuplicateOwnerEmailException(normalizedEmail);
394	        }
395	    }
396	
397	    /**
398	     * Rejects creating an owner who shares a household with any existing owner, unless the request
399	     * opts in with {@code sharesHousehold} set to {@code true}. Two owners share a household when they
400	     * have the same {@code lastName} and {@code address}, compared case-insensitively and with runs of
401	     * whitespace collapsed (see {@link HouseholdNormalizer}); the submitted fields and every existing
402	     * owner's stored fields are reduced to their {@linkplain HouseholdNormalizer#toComparisonKey
403	     * comparison key} before comparison. A match is reported as a {@code 409 Conflict}.
404	     *
405	     * @param ownerFieldsDto the submitted owner fields (its {@code lastName} and {@code address} are
406	     *                       non-blank here, {@link #rejectBlankOwnerFields} having already run)
407	     * @throws DuplicateOwnerHouseholdException if another owner already shares the household and the
408	     *                                          request did not opt in with {@code sharesHousehold}
409	     */
410	    /**
411	     * Counts the existing owners (before this create) whose {@code firstName} and {@code lastName}
412	     * both match the submitted values, compared case-insensitively. The count reflects only owners
413	     * already persisted at the time of the create, so the owner being created is never included.
414	     *
415	     * @param firstName the submitted first name (non-blank here, {@link #rejectBlankOwnerFields}
416	     *                  having already run)
417	     * @param lastName  the submitted last name (non-blank here)
418	     * @return the number of existing owners sharing the same first and last name
419	     */
420	    private int countNamesakes(String firstName, String lastName) {
421	        return (int) this.clinicService.findAllOwners().stream()
422	            .filter(owner -> firstName.equalsIgnoreCase(owner.getFirstName())
423	                && lastName.equalsIgnoreCase(owner.getLastName()))
424	            .count();
425	    }
426	
427	    /**
428	     * Counts the existing owners (before this create) belonging to the given household, i.e. those
429	     * whose stored {@code householdId} equals the value derived for the owner being created. The
430	     * count reflects only owners already persisted at the time of the create, so the owner being
431	     * created is never included; callers add one to obtain the household size after this create.
432	     *
433	     * @param householdId the household identifier derived for the owner being created (see
434	     *                    {@link HouseholdNormalizer#toHouseholdId})
435	     * @return the number of existing owners already sharing that household
436	     */
437	    private int countHouseholdMembers(String householdId) {
438	        if (householdId == null) {
439	            return 0;
440	        }
441	        return (int) this.clinicService.findAllOwners().stream()
442	            .map(Owner::getHouseholdId)
443	            .filter(householdId::equals)
444	            .count();
445	    }
446	
447	    /**
448	     * Rejects creating an owner whose city already holds {@link #MAX_OWNERS_PER_CITY} or more owners.
449	     * The submitted city is compared case-insensitively against every existing owner's stored city; a
450	     * city that is already at (or over) capacity is reported as a {@code 409 Conflict}.
451	     *
452	     * @param city the submitted city (non-blank here, {@link #rejectBlankOwnerFields} having already
453	     *             run)
454	     * @throws OwnerCityAtCapacityException if the city already contains the maximum number of owners
455	     */
456	    private void rejectCityAtCapacity(String city) {
457	        long ownersInCity = this.clinicService.findAllOwners().stream()
458	            .map(Owner::getCity)
459	            .filter(Objects::nonNull)
460	            .filter(city::equalsIgnoreCase)
461	            .count();
462	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
463	            throw new OwnerCityAtCapacityException(city);
464	        }
465	    }
466	
467	    /**
468	     * Resolves the effective registration date for a create, rolled onto a business day. The
469	     * supplied date is used when present, otherwise the server's current date; either way the result
470	     * is rolled forward to the next Monday when it falls on a Saturday or Sunday (see
471	     * {@link BusinessDayAdjuster#toBusinessDay}). Every value derived from the registration date - the
472	     * stored {@code registrationDate}, the membership number's year segment and the daily
473	     * create-limit's per-day count - is judged on this adjusted date.
474	     *
475	     * @param suppliedRegistrationDate the registration date from the request, or {@code null} to
476	     *                                 default to the server's current date
477	     * @return the effective registration date, guaranteed to fall on a business day
478	     */
479	    private LocalDate effectiveRegistrationDate(LocalDate suppliedRegistrationDate) {
480	        LocalDate registrationDate =
481	            suppliedRegistrationDate != null ? suppliedRegistrationDate : LocalDate.now();
482	        return BusinessDayAdjuster.toBusinessDay(registrationDate);
483	    }
484	
485	    /**
486	     * Rejects creating an owner once {@link #MAX_OWNERS_PER_DAY} or more owners have already been
487	     * created for the given business day, judged by their stored {@code registrationDate}. Only owners
488	     * already persisted (before this create) are counted, and only those whose {@code registrationDate}
489	     * equals the adjusted registration date; a day at (or over) that limit is reported as a {@code 429
490	     * Too Many Requests}.
491	     *
492	     * @param registrationDate   the create's effective registration date, already rolled onto a
493	     *                           business day by {@link #effectiveRegistrationDate}
494	     * @param registeredThatDay  the number of owners already persisted (before this create) whose
495	     *                           {@code registrationDate} equals {@code registrationDate}
496	     * @throws OwnerDailyRegistrationLimitException if that day has already reached the maximum number of
497	     *                                              owner registrations
498	     */
499	    private void rejectDailyRegistrationLimitReached(LocalDate registrationDate, long registeredThatDay) {
500	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
501	            throw new OwnerDailyRegistrationLimitException(registrationDate);
502	        }
503	    }
504	
505	    /**
506	     * Counts the owners already persisted (before this create) whose stored {@code registrationDate}
507	     * equals the given day. This is the shared per-day accumulation both the daily create-limit and the
508	     * bulk-signup warning are judged on.
509	     *
510	     * @param registrationDate the create's effective registration date, already rolled onto a business
511	     *                         day by {@link #effectiveRegistrationDate}
512	     * @return the number of existing owners registered on that day
513	     */
514	    private long countRegisteredOn(LocalDate registrationDate) {
515	        return this.clinicService.findAllOwners().stream()
516	            .map(Owner::getRegistrationDate)
517	            .filter(registrationDate::equals)
518	            .count();
519	    }
520	
521	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
522	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
523	            return;
524	        }
525	        String comparisonKey = HouseholdNormalizer.toComparisonKey(
526	            ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
527	        boolean inUse = this.clinicService.findAllOwners().stream()
528	            .filter(owner -> owner.getLastName() != null && owner.getAddress() != null)
529	            .map(owner -> HouseholdNormalizer.toComparisonKey(owner.getLastName(), owner.getAddress()))
530	            .anyMatch(comparisonKey::equals);
531	        if (inUse) {
532	            throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
533	        }
534	    }
535	}
